using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class UgoCreate {const string Folder=@"C:\Users\user\Desktop\02_Справочники_CAD_Revit\odnolineyka\_Разработка\ugo";const string Ref=@"\\Server\DropBox\Работа server\4. Техдепартамент\4.1. Проекты\098 Ташкент-КТ\5 ПИР\5.5_Том 4 Пост охраны\01_ELF-D1-03-ЭОМ\01_Титул.DWG";
[CommandMethod("CODEXUGOCREATEDRAFT",CommandFlags.Session)]public void Run(){var prior=HostApplicationServices.WorkingDatabase;try{using(var db=new Database(false,true)){db.ReadDwgFile(Ref,FileOpenMode.OpenForReadAndAllShare,false,null);db.CloseInput(true);HostApplicationServices.WorkingDatabase=db;
 var lm=LayoutManager.Current;lm.CurrentLayout="ОД (4)";var names=new List<string>();using(var tr=db.TransactionManager.StartTransaction()){var dict=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);foreach(DBDictionaryEntry en in dict)if(en.Key!="Model" && en.Key!="ОД (4)")names.Add(en.Key);}
 foreach(string name in names)lm.DeleteLayout(name);lm.RenameLayout("ОД (4)","УГО");
 var retained=new List<object>();ObjectId frameId=ObjectId.Null;var xrefs=new List<ObjectId>();using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);var model=(BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);foreach(ObjectId id in model){var e=(Entity)tr.GetObject(id,OpenMode.ForRead);bool keep=false;Extents3d ex=default;try{ex=e.GeometricExtents;keep=ex.MinPoint.X>=1060 && ex.MaxPoint.X<=1260 && ex.MaxPoint.Y<0 && ex.MinPoint.Y>=-330 && e.Layer!="Defpoints";}catch{}if(keep)retained.Add(new{Handle=e.Handle.ToString(),Type=e.GetType().Name,Min=new[]{ex.MinPoint.X,ex.MinPoint.Y},Max=new[]{ex.MaxPoint.X,ex.MaxPoint.Y}});else{e.UpgradeOpen();e.Erase();}}
 var ld=(DBDictionary)tr.GetObject(db.LayoutDictionaryId,OpenMode.ForRead);var layout=(Layout)tr.GetObject(ld.GetAt("УГО"),OpenMode.ForRead);var paper=(BlockTableRecord)tr.GetObject(layout.BlockTableRecordId,OpenMode.ForRead);foreach(ObjectId id in paper){if(tr.GetObject(id,OpenMode.ForRead) is BlockReference br){frameId=id;br.UpgradeOpen();foreach(DynamicBlockReferenceProperty prop in br.DynamicBlockReferencePropertyCollection)if(prop.PropertyName=="Видимость1")prop.Value="Форма 3";}}
 if(frameId.IsNull)throw new System.Exception("No title block");
 foreach(ObjectId id in bt){var b=(BlockTableRecord)tr.GetObject(id,OpenMode.ForRead);if(b.IsFromExternalReference){var path=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(Ref),b.PathName));if(!File.Exists(path))throw new System.Exception("Missing stamp reference: "+path);b.UpgradeOpen();b.PathName=path;xrefs.Add(id);}if(b.IsFromExternalReference)continue;foreach(ObjectId eid in b){if(tr.GetObject(eid,OpenMode.ForRead) is MText m){if(m.Text.Contains("ELF-D1-")){m.UpgradeOpen();m.Contents=m.Contents.Replace("ELF-D1-03-ЭОМ","ELF-D1-02-ЭОМ").Replace("ELF-D1-01-ЭОМ","ELF-D1-02-ЭОМ");}else if(m.Text.Trim()=="D100 КПП-1"||m.Text.Trim()=="D100"){m.UpgradeOpen();m.Contents="D100 ХБК";}}}}
 tr.Commit();}
 if(retained.Count!=19)throw new System.Exception("Wrong legend entity count: "+retained.Count);
 if(xrefs.Count>0){db.ResolveXrefs(false,false);db.ReloadXrefs(new ObjectIdCollection(xrefs.ToArray()));db.BindXrefs(new ObjectIdCollection(xrefs.ToArray()),false);}
 var output=Path.Combine(Folder,"УГО_ХБК_проверка.dwg");db.SaveAs(output,DwgVersion.Current);File.WriteAllText(Path.Combine(Folder,"draft.json"),JsonSerializer.Serialize(new{File=output,Retained=retained,Layout="УГО",Source=Ref,FrameHandle=frameId.Handle.ToString(),XrefsBound=xrefs.Count},new JsonSerializerOptions{WriteIndented=true}));
 }}catch(System.Exception ex){File.WriteAllText(Path.Combine(Folder,"draft_error.txt"),ex.ToString());}finally{HostApplicationServices.WorkingDatabase=prior;}}
}